<?php
declare(strict_types=1);if(PHP_SAPI!=='cli')exit;$root=sys_get_temp_dir().'/victor-types-'.bin2hex(random_bytes(5));mkdir($root,0700);define('VICTOR_ADMIN_TEST_DIR',$root);require __DIR__.'/lib.php';require __DIR__.'/stock-matrix.php';session_save_path($root);session_start();ob_start();
function vc(bool $v,string $label){if(!$v)throw new RuntimeException('FAIL '.$label);echo 'PASS '.$label.PHP_EOL;}
try{file_put_contents($root.'/admin-config.json',json_encode(['username'=>'owner','version'=>'fixture','password_hash'=>'unused']));$_SESSION=['admin'=>true,'auth_version'=>'fixture'];$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);stock_schema($db);wb_schema($db);$db->exec("INSERT INTO stock_products VALUES('DTQ26','Fixture','Nam')");$s=wb_empty();$s['sheets']['orders']['name']='25/11 NAM';$s['sheets']['orders']['cellData'][1]=[4=>['v'=>'DTQ26 L × 2'],7=>['v'=>'C25/L']];wb_store($db,$s,[],0,'fixture');
$user=['username'=>'owner'];$save=static function($kind,$variant,$qty,$extra=[])use($db,$user){return stock_matrix_save($db,$extra+['request_key'=>sprintf('%08x-1111-4111-a111-111111111111',random_int(1,99999999)),'sku'=>'DTQ26','kind'=>$kind,'variant'=>$variant,'quantities'=>['L'=>$qty],'note'=>'Fixture','token'=>stock_matrix($db)['token']],$user);};
$save('receipt','',8);$before=stock_matrix($db);stock_variant_save($db,['sku'=>'DTQ26','label'=>'Xấu','priority'=>1],$user);$get=static function($variant)use($db){foreach(stock_matrix($db)['variantBalances'] as $b)if($b['sku']==='DTQ26'&&$b['size']==='L'&&$b['variant']===$variant)return $b['balance'];return 0;};vc($get('')===6,'enabling type preserves prior shipments and default balance');vc(stock_matrix($db)['balances']===$before['balances'],'enabling type does not change aggregate');
$save('receipt','Xấu',7);vc($get('Xấu')===7&&$get('')===6,'receipt assigned only selected type');
$key='11111111-1111-4111-a111-111111111111';$save('stocktake','Xấu',5,['request_key'=>$key]);$save('stocktake','Xấu',5,['request_key'=>$key]);vc($get('Xấu')===5&&$get('')===6,'type stocktake absolute and retries idempotent');
$b=$save('receipt','Xấu',2);$save('receipt','Xấu',4,['id'=>$b['id'],'revision'=>1]);vc($get('Xấu')===9,'editing receipt posts type-specific delta');
$bad=false;try{$save('receipt','Unknown',1);}catch(RuntimeException $e){$bad=$e->getCode()===400;}vc($bad,'unknown type rejected');
$db->prepare("UPDATE stock_movements SET quantity=quantity+1 WHERE id=(SELECT MIN(id) FROM stock_movements)")->execute();$bad=false;try{$save('stocktake','Xấu',0,['token'=>'outdated']);}catch(RuntimeException $e){$bad=$e->getCode()===409;}vc($bad,'stale stocktake rejected');
vc(count(stock_matrix($db)['variantDispatch'])===1,'dispatch types available for warehouse audit');echo "STOCK_TYPES_INTEGRATION_COMPLETE\n";
}finally{session_write_close();ob_end_flush();foreach(glob($root.'/*') as $file)unlink($file);rmdir($root);}
